using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace EmployeeMonitoringAPI.Controllers;
[Route("api/[controller]")][ApiController][Authorize]
public sealed class DashboardController:ControllerBase
{
 private readonly ApplicationDbContext _db;public DashboardController(ApplicationDbContext db){_db=db;}
 [HttpGet("admin-summary")][Authorize(Roles="Admin")]
 public async Task<ActionResult<AdminDashboardSummaryDto>> AdminSummary(){var now=DateTime.UtcNow;var today=now.Date;var userId=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var projects=await _db.Projects.AsNoTracking().Include(x=>x.Manager).Where(x=>!x.IsArchived).ToListAsync();var delayed=projects.Where(x=>x.Status=="Delayed"||(x.EndDate.Date<today&&x.Status!="Completed")).ToList();var meetingRows=await _db.CalendarEvents.AsNoTracking().Where(x=>x.EventType=="Meeting"&&x.Status=="Scheduled"&&x.StartTime>=now).OrderBy(x=>x.StartTime).ToListAsync();var meetings=meetingRows.GroupBy(x=>x.MeetingGroupId).Select(x=>x.First()).Take(5).ToList();var holidays=await _db.CompanyHolidays.AsNoTracking().Where(x=>x.IsActive&&x.HolidayDate>=today).OrderBy(x=>x.HolidayDate).Take(5).ToListAsync();var alerts=new List<SystemAlertDto>();var primaryCount=await _db.Users.CountAsync(x=>x.Role=="Admin"&&x.IsPrimaryAdmin&&x.IsActive);if(primaryCount!=1)alerts.Add(new(){Code="PRIMARY_ADMIN",Title="Primary Admin configuration",Message=$"Expected one active Primary Admin; found {primaryCount}.",Severity="Critical"});var adminWithoutMfa=await _db.Users.CountAsync(x=>x.Role=="Admin"&&x.IsActive&&!x.MfaEnabled);if(adminWithoutMfa>0)alerts.Add(new(){Code="ADMIN_MFA",Title="Admin MFA policy",Message=$"{adminWithoutMfa} active Admin account(s) rely on the global MFA requirement.",Severity="Warning"});var year=now.Year;var quarters=Enumerable.Range(1,4).Select(q=>{var start=new DateTime(year,(q-1)*3+1,1,0,0,0,DateTimeKind.Utc);var end=start.AddMonths(3);var rows=projects.Where(x=>x.CreatedAt>=start&&x.CreatedAt<end).ToList();return new QuarterProjectDto{Year=year,Quarter=$"Q{q}",Completed=rows.Count(x=>x.Status=="Completed"),Delayed=rows.Count(x=>x.Status=="Delayed"||(x.EndDate<now&&x.Status!="Completed")),AverageProgress=rows.Count==0?0:Math.Round((decimal)rows.Average(x=>x.ProgressPercentage),2)};}).ToList();var activity=await _db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.Timestamp).Take(8).Select(x=>new AdminDashboardActivityDto{Id=x.Id,Action=x.Action,Timestamp=x.Timestamp,ActorName=_db.Users.Where(u=>u.UserId==x.ActorUserId).Select(u=>u.FullName).FirstOrDefault()}).ToListAsync();var notifications=await _db.Notifications.AsNoTracking().Where(x=>x.UserId==userId).OrderByDescending(x=>x.CreatedAt).Take(8).Select(x=>new AdminDashboardNotificationDto{Id=x.Id,Title=x.Title,Message=x.Message,IsRead=x.IsRead,CreatedAt=x.CreatedAt}).ToListAsync();return Ok(new AdminDashboardSummaryDto{ActiveDepartments=await _db.Departments.CountAsync(x=>x.IsActive),ActiveManagers=await _db.Users.CountAsync(x=>x.Role=="Manager"&&x.IsActive),ActiveProjects=projects.Count,UnreadNotifications=await _db.Notifications.CountAsync(x=>x.UserId==userId&&!x.IsRead),DepartmentsWithoutManager=await _db.Departments.CountAsync(d=>d.IsActive&&!_db.Users.Any(u=>u.DepartmentId==d.Id&&u.Role=="Manager"&&u.IsActive)),ProjectsWithoutManager=projects.Count(x=>!x.ManagerId.HasValue),DelayedProjects=delayed.Count,UpcomingMeetingCount=meetingRows.Select(x=>x.MeetingGroupId).Distinct().Count(),UpcomingHolidayCount=await _db.CompanyHolidays.CountAsync(x=>x.IsActive&&x.HolidayDate>=today),InactiveDepartments=await _db.Departments.CountAsync(x=>!x.IsActive),SecurityWarningCount=alerts.Count,ProjectStatuses=projects.GroupBy(x=>x.Status).Select(x=>new AdminProjectStatusDto{Status=x.Key,Count=x.Count()}).ToList(),QuarterlyProjectOverview=quarters,RecentProjectProgress=projects.OrderByDescending(x=>x.UpdatedAt).Take(6).Select(x=>new ProjectProgressDto{ProjectId=x.ProjectId,ProjectName=x.ProjectName,ManagerName=x.Manager?.FullName,Status=x.Status,ProgressPercentage=x.ProgressPercentage}).ToList(),UpcomingMeetings=meetings.Select(x=>new UpcomingMeetingDto{Id=x.EventId,Title=x.Title,StartTime=x.StartTime,Location=x.Location}).ToList(),UpcomingHolidays=holidays.Select(x=>new UpcomingHolidayDto{Id=x.HolidayId,Title=x.HolidayName,Date=x.HolidayDate}).ToList(),RecentActivities=activity,RecentNotifications=notifications,SystemAlerts=alerts});}
 [HttpGet("hr-summary")][Authorize(Roles="HR")]
 public async Task<IActionResult> HrSummary()=>Ok(new{totalEmployees=await _db.Users.CountAsync(x=>x.Role=="Employee"),activeEmployees=await _db.Users.CountAsync(x=>x.Role=="Employee"&&x.IsActive),departments=await _db.Departments.CountAsync(),managers=await _db.Users.CountAsync(x=>x.Role=="Manager")});
 [HttpGet("attendance-chart")][Authorize(Roles="Admin,Manager,HR")]
 public async Task<IActionResult> AttendanceChart()=>Ok(await _db.Attendances.AsNoTracking().Where(x=>x.User!=null&&x.User.Role=="Employee").GroupBy(x=>x.AttendanceDate.Date).Select(g=>new{date=g.Key,totalEmployees=g.Count()}).OrderBy(x=>x.date).ToListAsync());
 [HttpGet("project-chart")][Authorize(Roles="Admin,Manager,HR")]
 public async Task<IActionResult> ProjectChart()=>Ok(new{ongoing=await _db.Projects.CountAsync(x=>!x.IsArchived&&x.Status=="Ongoing"),completed=await _db.Projects.CountAsync(x=>!x.IsArchived&&x.Status=="Completed"),queued=await _db.Projects.CountAsync(x=>!x.IsArchived&&x.Status=="Queued")});
 [HttpGet("leave-chart")][Authorize(Roles="Manager,HR")]
 public async Task<IActionResult> LeaveChart()=>Ok(new{approved=await _db.Leaves.CountAsync(x=>x.Status=="Approved"),pending=await _db.Leaves.CountAsync(x=>x.Status=="Pending"),rejected=await _db.Leaves.CountAsync(x=>x.Status=="Rejected")});}